  const result = vatSummary([invoice]);

  assert.equal(result.length, 1);
  assert.ok(result[0].rate);
  assert.ok(result[0].base);
  assert.ok(result[0].vat);
});

test('vatSummary includes partially_paid invoices', () => {
  const issued = createIssuedInvoice('C-001', '2024-01-15', '2024-02-14');
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-15' }).value;

  const result = vatSummary([partial]);

  assert.equal(result.length, 1);
  assert.ok(result[0].base > 0);
});

test('vatSummary includes paid invoices', () => {
  const issued = createIssuedInvoice('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2024-02-15' }).value;

