test('vatSummary excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = createIssuedInvoice();

  const result = vatSummary([draft, issued]);

  assert.equal(result.length, 1);
  assert.ok(result[0].base > 0);
