test('vatSummary handles multiple VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },    // 21% VAT
      { sku: 'PRINT-A4', qty: 10 },   // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 3);
  assert.ok(result.some(r => r.rate === 21));
  assert.ok(result.some(r => r.rate === 9));
  assert.ok(result.some(r => r.rate === 0));
});

test('vatSummary sorts by rate descending', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },     // 21% VAT
      { sku: 'PRINT-A4', qty: 10 },    // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);
});

test('vatSummary calculates base as line total minus discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 }, // 8500 - 850 = 7650 base
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  // DES-HOUR is 8500 cents, with 10% discount = 850, base = 7650
  assert.equal(result[0].base, 7650);
});

test('vatSummary calculates VAT on discounted base', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  // DES-HOUR is 8500 cents, gold tier 5% discount = 425, base = 8075
  // VAT is 8075 * 21% = 1695.75 -> 1696
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 8075);
  assert.equal(result[0].vat, 1696);
});

test('vatSummary aggregates multiple invoices with same rate', () => {
  const invoice1 = createIssuedInvoice('C-001', '2024-01-15', '2024-02-14');
  const invoice2 = createIssuedInvoice('C-002', '2024-01-20', '2024-02-19');

  const result = vatSummary([invoice1, invoice2]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Both invoices have same line, so base and VAT should be doubled
  assert.ok(result[0].base > 0);
  assert.ok(result[0].vat > 0);
});

test('vatSummary aggregates rates correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },     // 21% VAT
      { sku: 'DES-HOUR', qty: 1 },     // 21% VAT again
      { sku: 'PRINT-A4', qty: 5 },     // 9% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  const rate21 = result.find(r => r.rate === 21);
  const rate9 = result.find(r => r.rate === 9);
  assert.ok(rate21.base > 0);
  assert.ok(rate9.base > 0);
});

test('vatSummary with vouchers (vouchers do not affect VAT)', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const withVoucher = applyVoucher(draft, { code: 'TEST', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const result = vatSummary([issued]);

  // VAT is calculated on the base (after line discounts), not affected by voucher
  assert.equal(result.length, 1);
  assert.ok(result[0].vat > 0);
});

test('vatSummary returns empty array for empty invoices list', () => {
  const result = vatSummary([]);

  assert.equal(result.length, 0);
  assert.ok(Array.isArray(result));
});

test('vatSummary with zero VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
