test('vatSummary calculates base as line total minus discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 }, // 8500 - 850 = 7650 base
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  // DES-HOUR is 8500 cents, with 10% discount = 850, base = 7650
  assert.equal(result[0].base, 7650);
});

test('vatSummary calculates VAT on discounted base', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  // DES-HOUR is 8500 cents, explicit 0% discount overrides tier, so base = 8500
  // VAT is 8500 * 21% = 1785
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 8500);
  assert.equal(result[0].vat, 1785);
});

test('vatSummary aggregates multiple invoices with same rate', () => {
  const invoice1 = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const invoice2 = createIssuedWithDueDate('C-002', '2024-01-20', '2024-02-19');

  const result = vatSummary([invoice1, invoice2]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Both invoices have same line, so base and VAT should be doubled
  assert.ok(result[0].base > 0);
  assert.ok(result[0].vat > 0);
});

test('vatSummary aggregates rates correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },     // 21% VAT
      { sku: 'DES-HOUR', qty: 1 },     // 21% VAT again
      { sku: 'PRINT-A4', qty: 5 },     // 9% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  const rate21 = result.find(r => r.rate === 21);
  const rate9 = result.find(r => r.rate === 9);
  assert.ok(rate21.base > 0);
  assert.ok(rate9.base > 0);
});

test('vatSummary with vouchers (vouchers do not affect VAT)', () => {
